let stars = [];
let planets = [];
let asteroids = [];
let timeSpeed = 1;

function setup() {
  createCanvas(800, 600);
  textAlign(CENTER, CENTER);
  for (let i = 0; i < 100; i++) {
    stars.push({ x: random(width), y: random(height), s: random(1, 3) });
  }
  planets = [
    { name: 'Mercury', dist: 50, radius: 4, speed: 0.04, angle: random(TWO_PI), col: [180, 180, 180] },
    { name: 'Venus', dist: 80, radius: 7, speed: 0.025, angle: random(TWO_PI), col: [230, 190, 130] },
    { name: 'Earth', dist: 120, radius: 8, speed: 0.018, angle: random(TWO_PI), col: [80, 150, 240] },
    { name: 'Mars', dist: 160, radius: 6, speed: 0.014, angle: random(TWO_PI), col: [220, 90, 60] },
    { name: 'Jupiter', dist: 215, radius: 15, speed: 0.008, angle: random(TWO_PI), col: [210, 170, 130] },
    { name: 'Saturn', dist: 270, radius: 12, speed: 0.006, angle: random(TWO_PI), col: [235, 210, 150] },
    { name: 'Uranus', dist: 320, radius: 10, speed: 0.004, angle: random(TWO_PI), col: [140, 220, 230] },
    { name: 'Neptune', dist: 365, radius: 9, speed: 0.003, angle: random(TWO_PI), col: [70, 110, 230] }
  ];
  for (let i = 0; i < 40; i++) {
    asteroids.push({
      dist: random(180, 195),
      angle: random(TWO_PI),
      speed: random(0.009, 0.012),
      radius: random(1.5, 3)
    });
  }
}

function draw() {
  background(10, 12, 24);

  noStroke();
  fill(255, 255, 255, 180);
  for (let i = 0; i < stars.length; i++) {
    circle(stars[i].x, stars[i].y, stars[i].s);
  }

  push();
  translate(width / 2, height / 2);

  noFill();
  stroke(255, 255, 255, 30);
  strokeWeight(1);
  for (let i = 0; i < planets.length; i++) {
    circle(0, 0, planets[i].dist * 2);
  }

  noStroke();
  fill(160, 150, 140, 150);
  for (let i = 0; i < asteroids.length; i++) {
    let a = asteroids[i];
    a.angle += a.speed * timeSpeed;
    let ax = cos(a.angle) * a.dist;
    let ay = sin(a.angle) * a.dist;
    circle(ax, ay, a.radius);
  }

  fill(255, 204, 0);
  circle(0, 0, 36);
  fill(255, 240, 150, 70);
  circle(0, 0, 48);

  for (let i = 0; i < planets.length; i++) {
    let p = planets[i];
    p.angle += p.speed * timeSpeed;
    let px = cos(p.angle) * p.dist;
    let py = sin(p.angle) * p.dist;

    fill(p.col[0], p.col[1], p.col[2]);
    circle(px, py, p.radius * 2);

    if (p.name === 'Saturn') {
      noFill();
      stroke(200, 180, 140, 160);
      strokeWeight(2);
      ellipse(px, py, p.radius * 3.4, p.radius * 1.4);
      noStroke();
    }
  }
  pop();

  fill(220);
  textSize(14);
  text('Tiny Solar System - Click to toggle speed', width / 2, 25);
}

function mousePressed() {
  timeSpeed = timeSpeed === 1 ? 2.5 : 1;
}
